export type AddMessageArgs = { godMode?: boolean; at?: number; chatId: number; role: string; text: string; images?: string[], isImageRequest?: boolean, videos?: string[], isVideoRequest?: boolean, videoPrompt?: string, isImpersonated?: boolean, emotion?: string, imagePrompt?: string, imageParams?: any, speakerId?: number, isRefusal?: boolean, isNarration?: boolean, thoughts?: string, isVoiceNote?: boolean, beat?: number, choices?: Message["choices"], secretRevealed?: boolean, notes?: Message["notes"], swapped?: boolean, noGreeting?: boolean, quotedStatus?: Message["quotedStatus"], replyTo?: Message["replyTo"], forward?: Message["forward"], poll?: Message["poll"] };

// `saved` goes with the result: the chat as written, for addMessage.fulfilled.
export const addMessage = createAsyncThunk<Message[], AddMessageArgs, { fulfilledMeta: { saved: Chat } }>(
  "chat/addMessage",
  lockedByChat(async ({ chatId, role, text, images, isImageRequest, videos, isVideoRequest, videoPrompt, isImpersonated, emotion, imagePrompt, imageParams, speakerId, isRefusal, isNarration, thoughts, isVoiceNote, beat, choices, secretRevealed, notes, swapped, noGreeting, quotedStatus, replyTo, forward, poll, at, godMode }: AddMessageArgs, { dispatch, getState, rejectWithValue, fulfillWithValue }) => {
    try {
      const chat = await dbService.getChatById(chatId);

      // If it's the first message, prepopulate with the primary character's
      // own greeting (if it has one) instead of the generic global initial
      // messages. For a room with several characters, only the first one
      // (characterIds[0]) greets - Phase 12's room creation flow decides
      // who that is. Skipped for an impersonated opener: the user is
      // dictating the character's own opening line themselves, so an
      // auto-inserted greeting ahead of it would just be a second,
      // unwanted "first" message.
      if (chat.content.length === 0 && !isImpersonated) {
        const primaryCharacterId = chat.characterIds?.[0];
        const character = primaryCharacterId ? await dbService.getCharacterById(primaryCharacterId).catch(() => undefined) : undefined;
        const greetings = getGreetings(character);
        // `noGreeting`: a character texting first (#93) opens the chat with
        // that text, not their roleplay greeting.
        if (character && greetings.length > 0 && !noGreeting) {
          // Unlike the generic seed messages below, this is a real visible greeting
          // (not a hidden priming message), so it's left unflagged as `isSystem`.
          // Whichever greeting was picked in the empty-state preview wins;
          // {{char}}/{{user}} are resolved now since the text is stored as-is.
          const greeting = greetings[Math.min(chat.greetingIndex || 0, greetings.length - 1)];
          const txt = applyMacros(greeting, { char: character.name, user: resolvePersonaName(getState, chat) || "User" });
          chat.content.push({ role: AI, txt, speakerId: character.id, id: generateNodeId(), timestamp: Date.now() });
        } else {
          const savedMessages = JSON.parse(localStorage.getItem(LS_INITIAL_MESSAGES) || "[]") as any[];
          savedMessages.forEach((msg) => {
            if (msg.role && msg.message) {
              chat.content.push({ role: msg.role, txt: msg.message, isSystem: true, id: generateNodeId(), timestamp: Date.now() });
            }
          });
        }
      }

      const newMessage: Message = { role, txt: text, images, isImageRequest, videos, isVideoRequest, videoPrompt, isImpersonated, emotion, imagePrompt, imageParams, speakerId, isRefusal, isNarration: isNarration || undefined, thoughts, isVoiceNote: isVoiceNote || undefined, beat, choices, secretRevealed: secretRevealed || undefined, notes: notes && notes.length > 0 ? notes : undefined, swapped: swapped || undefined, quotedStatus, replyTo, forward, poll, godMode: godMode || undefined, id: generateNodeId(), timestamp: at ?? Date.now() };

      // A real reply from the user - or the user speaking as the character via
      // Impersonate mode - both mean the user is actively here, so any pending
      // auto-follow-up streak is over.
      if ((role === YOU || isImpersonated) && chat.autoReply) {
        chat.autoReply = { ...chat.autoReply, followupCount: 0 };
      }

      if (chat.tree) {
        // Tree-aware chat (has been branched at least once): extend from the active leaf.
        const { tree, nodeId } = addChildNode(chat.tree, chat.activeLeafId || null, newMessage);
        chat.tree = tree;
        chat.activeLeafId = nodeId;
        chat.content = flattenPath(tree, nodeId);
      } else {
        chat.content.push(newMessage);
      }

      await dbService.updateChat(chat);
      dispatch(fetchChats()); // Refresh state
      // The saved chat goes on screen too (see addMessage.fulfilled): this
      // marks the chat as changed, and a refresh that read it before the
      // write would otherwise keep a copy on screen without the message.
      return fulfillWithValue(chat.content, { saved: chat });
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  })
);

