// "Undo compression": takes a summary pair back out (removeSummaryFromConversation).
export const removeCompressionSummary = createAsyncThunk(
  "chat/removeCompressionSummary",
  lockedByChat(async ({ chatId, summaryId }: { chatId: number; summaryId: string }, { rejectWithValue }) => {
    try {
      const chat = await dbService.getChatById(chatId);
      const result = removeSummaryFromConversation(chat, summaryId);
      if (!result) throw new Error("That summary isn't in this chat any more.");
      chat.tree = result.tree;
      chat.activeLeafId = result.activeLeafId;
      chat.content = result.content;
      await dbService.updateChat(chat);
      return { chatId, ...result };
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  })
);

// Splices a compression summary pair into the chat right after the last
// message it covers, without deleting anything: the summarized messages and
// every branch stay in the tree, and the prompt starts from the newest
// summary (trimToLatestSummary). See spliceSummaryIntoConversation.
export const insertCompressionSummary = createAsyncThunk(
  "chat/insertCompressionSummary",
  lockedByChat(async (
    { chatId, afterMessageId, afterIndex, summaryMessages }: { chatId: number; afterMessageId?: string; afterIndex: number; summaryMessages: Message[] },
    { rejectWithValue }
  ) => {
    try {
      const chat = await dbService.getChatById(chatId);
      const spliced = spliceSummaryIntoConversation(chat, afterMessageId, afterIndex, summaryMessages);
      if (!spliced) throw new Error("Couldn't find where to place the summary.");
      chat.tree = spliced.tree;
      chat.activeLeafId = spliced.activeLeafId;
      chat.content = spliced.content;
      await dbService.updateChat(chat);
      return { chatId, ...spliced };
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  })
);

// Patches fields on one message (e.g. renaming a chapter) in both the
// flattened content and, if present, its tree node, without moving it.
export const updateChatMessage = createAsyncThunk(
  "chat/updateChatMessage",
  // `patch` may be worked out from the message as saved (reactions: two
  // members reacting at once each keep theirs), inside the chat's lock.
  lockedByChat(async ({ chatId, messageId, patch }: { chatId: number; messageId: string; patch: Partial<Message> | ((saved: Message) => Partial<Message>) }, { rejectWithValue }) => {
    try {
      const chat = await dbService.getChatById(chatId);
      const node = chat.tree?.nodes[messageId];
      const saved = node?.message || chat.content.find((m) => m.id === messageId);
      if (!saved) return { chatId, content: chat.content, tree: chat.tree };
      const change = typeof patch === "function" ? patch(saved) : patch;
      chat.content = chat.content.map((m) => (m.id === messageId ? { ...m, ...change } : m));
      if (chat.tree && node) {
        chat.tree = { nodes: { ...chat.tree.nodes, [messageId]: { ...node, message: { ...node.message, ...change } } } };
      }
      await dbService.updateChat(chat);
      return { chatId, content: chat.content, tree: chat.tree };
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  })
);

