// Updates just a room's own group-scoped memory (Scene panel, and the
// auto-extraction interval when the chat is a room) - see Chat.memory.
// Meaningless for a 1:1 chat, which reads/writes the character's own
// Character.memory instead and never touches this field.
export const updateChatMemory = createAsyncThunk(
  "chat/updateChatMemory",
  lockedByChat(async (
    { chatId, memory, pinnedMemory, memoryCategories, memoryDates, memoryStanding }: { chatId: number; memory: Chat["memory"]; pinnedMemory?: Chat["pinnedMemory"]; memoryCategories?: Chat["memoryCategories"] | null; memoryDates?: Chat["memoryDates"] | null; memoryStanding?: Chat["memoryStanding"] },
    { rejectWithValue }
  ) => {
    try {
      const chat = await dbService.getChatById(chatId);
      chat.memory = memory;
      if (pinnedMemory !== undefined) chat.pinnedMemory = pinnedMemory;
      // undefined leaves the categories alone; null clears them.
      if (memoryCategories !== undefined) chat.memoryCategories = memoryCategories || undefined;
      if (memoryDates !== undefined) chat.memoryDates = memoryDates || undefined;
      if (memoryStanding) chat.memoryStanding = memoryStanding;
      await dbService.updateChat(chat);
      return { chatId, memory, pinnedMemory: chat.pinnedMemory, memoryCategories: chat.memoryCategories, memoryDates: chat.memoryDates, memoryStanding: chat.memoryStanding };
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  })
);

// Switches a 1:1 chat between sharing its character's memory and keeping
// its own. The first switch to "chat" starts the chat's memory as a copy of
// the character's (passed in as `seed`), so it still knows the backstory.
export const updateChatMemoryScope = createAsyncThunk(
  "chat/updateChatMemoryScope",
  lockedByChat(async (
    { chatId, memoryScope, seed }: { chatId: number; memoryScope: "character" | "chat"; seed?: Pick<Chat, "memory" | "pinnedMemory" | "memoryCategories" | "memoryDates"> },
    { rejectWithValue }
  ) => {
    try {
      const chat = await dbService.getChatById(chatId);
      chat.memoryScope = memoryScope === "chat" ? "chat" : undefined;
      const isEmpty = !(chat.memory?.length || chat.pinnedMemory?.length);
      if (memoryScope === "chat" && isEmpty && seed) {
        chat.memory = seed.memory ? [...seed.memory] : undefined;
        chat.pinnedMemory = seed.pinnedMemory ? [...seed.pinnedMemory] : undefined;
        chat.memoryCategories = seed.memoryCategories ? { ...seed.memoryCategories } : undefined;
        chat.memoryDates = seed.memoryDates ? { ...seed.memoryDates } : undefined;
      }
      await dbService.updateChat(chat);
      return { chatId, memoryScope: chat.memoryScope, memory: chat.memory, pinnedMemory: chat.pinnedMemory, memoryCategories: chat.memoryCategories, memoryDates: chat.memoryDates };
    } catch (error) {
      return handleDbError(error, rejectWithValue);
    }
  })
);

